describe('Session Expiration Test', () => {
    beforeEach(() => {
        cy.visit('/login');
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="password"]').type('password123');
        cy.get('button[type="submit"]').click();
        cy.url().should('include', '/dashboard');
    });

    it('should remain logged in during activity', () => {
        cy.get('h1').should('contain', 'Welcome to your dashboard');
        cy.wait(1000); // Simulate user activity
        cy.get('button#refresh').click(); // Simulate another action
        cy.url().should('include', '/dashboard');
    });

    it('should log out after 30 minutes of inactivity', () => {
        cy.wait(1800000); // Wait for 30 minutes
        cy.reload(); // Reload the page to check session status
        cy.url().should('include', '/login');
        cy.get('.alert').should('contain', 'Your session has expired. Please log in again.');
    });
});
